WITH inner_cte AS ( SELECT t1.SUBJECT_CODE, t1.SUBJECT_CODE_DESC, t0.DEPARTMENT_NAME, t1.SCHOOL_NAME, AVG(t0.DEPT_BUDGET_CODE) OVER (PARTITION BY t1.SCHOOL_NAME ORDER BY t0.DEPARTMENT_NAME) AS avg_dept_budget_code FROM SIS_DEPARTMENT t0 JOIN SIS_SUBJECT_CODE t1 ON t0.SCHOOL_CODE = t1.SCHOOL_CODE WHERE t0.IS_DEGREE_GRANTING = 'Y' AND t0.DEPARTMENT_NAME = 'Mathematics' ORDER BY t0.DEPARTMENT_NAME ) SELECT icte.SUBJECT_CODE, icte.SUBJECT_CODE_DESC, icte.DEPARTMENT_NAME, icte.SCHOOL_NAME, icte.avg_dept_budget_code, sos.SUBJECT_TITLE, sos.TOTAL_UNITS, DENSE_RANK() OVER (PARTITION BY d.DEPARTMENT_CODE ORDER BY d.DEPARTMENT_CODE) AS window_column, dept_subject_counts.subject_count FROM inner_cte icte JOIN SIS_DEPARTMENT d ON icte.DEPARTMENT_NAME = d.DEPARTMENT_NAME AND icte.SCHOOL_NAME = d.SCHOOL_NAME JOIN SIS_SUBJECT_CODE sc ON d.DEPARTMENT_CODE = sc.DEPARTMENT_CODE JOIN SUBJECT_OFFERED_SUMMARY sos ON sc.DEPARTMENT_CODE = sos.OFFER_DEPT_CODE JOIN ( SELECT d2.DEPARTMENT_CODE, COUNT(sos2.SUBJECT_OFFERED_SUMMARY_KEY) AS subject_count FROM SIS_DEPARTMENT d2 JOIN SUBJECT_OFFERED_SUMMARY sos2 ON d2.DEPARTMENT_CODE = sos2.OFFER_DEPT_CODE WHERE d2.IS_DEGREE_GRANTING = 'Y' AND d2.DEPARTMENT_NAME = 'Mathematics' GROUP BY d2.DEPARTMENT_CODE ) dept_subject_counts ON d.DEPARTMENT_CODE = dept_subject_counts.DEPARTMENT_CODE WHERE d.IS_DEGREE_GRANTING = 'Y' AND d.DEPARTMENT_NAME = 'Mathematics' ORDER BY icte.DEPARTMENT_NAME, window_column